-- ============================================================================
-- 14_mock_seed.sql · 企划星演示种子（企划 / 支持 / 社区）
-- ----------------------------------------------------------------------------
-- 执行顺序：00_all.sql（或 01..13） → 15_project_domain.sql → 本脚本
-- 数据基准日：2026-11-07 12:00（与 Flutter demo 的 DateTime.now() 对齐）。
-- 幂等说明：按单次执行设计，全部为普通 INSERT，不含 ON DUPLICATE KEY UPDATE。
--
-- 产品定位：企划星 = 企划支持平台。用户支持的是「企划能否落地」，
--           周边/内容/权益是回报，不是现货商品。
--
-- 数据来源 → 目标表
--   品类字典                 -> planstar_catalog.project_category / project_sub_tag
--   创作者主页与信用         -> planstar_catalog.creator_profile
--   企划主档                 -> planstar_catalog.project
--   回报档位                 -> planstar_catalog.reward_tier
--   进度更新                 -> planstar_catalog.project_update
--   解锁目标                 -> planstar_catalog.stretch_goal
--   常见问题                 -> planstar_catalog.project_faq
--   评价晒单                 -> planstar_catalog.project_review
--   举报风控                 -> planstar_catalog.project_report
--   组队支持                 -> planstar_catalog.support_team / support_team_member
--   支持记录                 -> planstar_order.pledge
--   支付与退款               -> planstar_payment.payment / refund（与 pledge 一一对应）
--   营销（支持立减/礼品卡）  -> planstar_marketing.coupon / campaign / gift_card / gift_card_usage
--   社区（企划种草/日志）    -> planstar_community.feed / feed_media / topic
--
-- 映射约定
--   1) 主键 id 一律省略（AUTO_INCREMENT）；业务 ID 使用固定可读编号：
--      project 1001..5002 / reward_tier = project_id*100 + 档位序号
--      project_update / project_faq / stretch_goal = project_id*100 + 序号
--      pledge 6001+ / payment 13001+（= 13000 + pledge_id - 6000）/ refund 14015+
--      support_team 7001+ / support_team_member 7101+
--   2) 金额写 DECIMAL 数字；时间写 'YYYY-MM-DD HH:MM:SS'；布尔写 0/1；
--      JSON 列为合法 JSON 字符串（单引号包裹、内部双引号）。
--   3) 企划状态覆盖：ongoing（进行中）/ achieved（已达成）/ delivered（已交付）/ failed（未达成退款）。
--   4) 四大核心品类：游戏、小说、同人、面经；扩展：画集设定集、音乐影像、校园活动、其他。
--   5) 原演出票务、座位图、代抢、拼团数据不再生成；票务能力仅作为线下回报的可选履约方式保留在表结构中。
--   6) 未生成：banner / home_floor / search_keyword / wallet_* 等与本期定位无关的演示数据；
--      project_review / project_report 为 P2 能力，仅生成已交付企划的评价与风控样本。
-- ============================================================================

SET NAMES utf8mb4;

USE `planstar_user`;
-- user_info · 演示用户（创作者 + 支持者）

-- user_address · 收货地址（周边回报履约）

-- real_name_info · 实名认证（创作者与线下回报）

-- user_message · 消息中心

-- chat_thread / chat_message · 创作者与支持者沟通


USE `planstar_catalog`;
-- project_category · 企划一级品类（白名单）

-- project_sub_tag · 企划二级标签

-- creator_profile · 创作者主页与信用（认证 / 历史企划 / 履约率）

-- project · 企划主档（32 个，覆盖 game/novel/fanwork/interview + 扩展品类）

-- project · 退款规则可视化文案（未达成全额原路退回 / 达成后按交付约定）
UPDATE `project`
SET `refund_rule` = '未达成：支持金额原路全额退回，平台不收手续费；达成后进入交付流程，除回报质量问题外不支持无理由退款。',
    `refund_days` = 7
WHERE `is_all_or_nothing` = 1;

UPDATE `project`
SET `refund_rule` = '未达成：支持金额原路全额退回；达成后按回报档位约定交付，除回报质量问题外不支持退款。',
    `refund_days` = 15
WHERE `is_all_or_nothing` = 0;

-- reward_tier · 回报档位（每企划 4–5 档，覆盖周边/电子内容/权益/线下参与）

-- project_update · 进度更新（进行中企划 3 条，已达成/已交付 2–3 条）

-- stretch_goal · 解锁目标

-- project_faq · 常见问题（退款规则可视化）

-- project_review · 评价与晒单（仅已交付企划的已交付支持记录，rating 3–5）

-- project_report · 举报与风控处理单（覆盖 project/review/feed 三类对象与三种处理状态）

-- support_team / support_team_member · 组队支持（替代原拼团票务心智）


USE `planstar_order`;
-- pledge · 支持记录（90 条，覆盖 paid/confirmed/delivered/refunded）

USE `planstar_marketing`;
-- coupon · 企划支持立减券

-- campaign · 企划支持季

USE `planstar_payment`;
-- payment · 企划支持支付单（每个 pledge 一条，pay_id = 13000 + pledge_id - 6000）
SELECT 13000 + (p.`pledge_id` - 6000), p.`pledge_id`, p.`support_amount`,
       CONCAT('支持企划 ', p.`project_id`), p.`project_id`,
       CONCAT('企划支持单 ', p.`pledge_no`), 1, p.`quantity`, 1, p.`paid_time`, p.`paid_time`
FROM `planstar_order`.`pledge` p
ORDER BY p.`pledge_id`;

-- refund · 退款单（仅 refunded 支持记录，refund_id 与 pledge.refund_id 一一对齐）
SELECT p.`refund_id`, p.`pledge_id`, p.`user_id`, p.`support_amount`, 'other',
       '企划未达成，按《未达成退款规则》原路退回', 'success', p.`gmt_modified`, p.`gmt_modified`
FROM `planstar_order`.`pledge` p
WHERE p.`pledge_status` = 'refunded' AND p.`refund_id` IS NOT NULL
ORDER BY p.`refund_id`;

-- 回填支持记录 → 支付单关联（消除 pledge.payment_id 悬空）
UPDATE `planstar_order`.`pledge`
SET `payment_id` = 13000 + (`pledge_id` - 6000)
WHERE `payment_id` IS NULL;

-- 履约字段按交付方式分流：物流单号仅 physical，数字内容仅 digital，权益核销仅 right/offline
UPDATE `planstar_order`.`pledge`
SET `tracking_no` = NULL
WHERE `delivery_type` IN ('digital', 'right', 'offline', 'none');

UPDATE `planstar_order`.`pledge`
SET `content_url` = CONCAT('https://cdn.planstar.cn/pledge/', `pledge_no`, '/download')
WHERE `delivery_type` = 'digital' AND `pledge_status` = 'delivered';

UPDATE `planstar_order`.`pledge`
SET `redeem_code` = CONCAT('RDM', `pledge_id`),
    `redeemed_time` = `delivered_time`
WHERE `delivery_type` IN ('right', 'offline') AND `pledge_status` = 'delivered';

-- gift_card · 支持礼品卡（可赠送给朋友用于支持企划）

-- gift_card_usage · 礼品卡抵扣支持（金额与对应 pledge.support_amount 一致）

USE `planstar_community`;
-- topic · 企划社区话题

-- feed · 企划种草 / 创作日志 / 开箱晒单 / 面经互助 / 答疑

-- feed_media · 仅保留有媒体内容的动态占位（URL 由客户端 CDN 补全）
-- 说明：mock 未提供真实图片，feed_media 生成为空集，避免伪造资源地址。

