INSERT INTO `project_review` (`review_id`, `project_id`, `pledge_id`, `user_id`, `rating`, `content`, `images`, `is_show`, `is_anonymous`, `like_count`, `status`, `gmt_create`, `gmt_modified`) VALUES
  (8001, 2006, 6001, 1, 5, '数字设定集排版很用心，附赠的分镜稿比预期多，值回支持价。', '[]', 0, 0, 46, 1, '2026-10-20 20:10:00', '2026-10-20 20:10:00'),
  (8002, 3001, 6003, 15, 5, '画集印刷和色彩都超出预期，签名页也没有折痕，包装很稳。', '[]', 1, 0, 132, 1, '2026-10-21 19:30:00', '2026-10-21 19:30:00'),
  (8003, 5002, 6020, 14, 4, '核销流程很顺，现场扫码入场不到一分钟，就是周边领取排了会儿队。', '[]', 0, 0, 58, 1, '2026-10-22 21:00:00', '2026-10-22 21:00:00'),
  (8004, 1003, 6022, 28, 5, '游戏完整度很高，四季作物和岛民剧情都能玩到，没有半成品感。', '[]', 0, 0, 88, 1, '2026-10-23 12:20:00', '2026-10-23 12:20:00'),
  (8005, 2002, 6025, 19, 4, '电子书排版舒服，番外收尾很温柔，希望后续能出实体版。', '[]', 0, 0, 37, 1, '2026-10-24 22:15:00', '2026-10-24 22:15:00'),
  (8006, 3004, 6026, 26, 5, '手办细节到位，底座刻字清晰，开箱拍照完全不用修图。', '[]', 1, 0, 205, 1, '2026-10-25 18:40:00', '2026-10-25 18:40:00'),
  (8007, 3008, 6027, 3, 5, '桌游规则书逻辑清楚，一局 40 分钟刚好，配件厚度也够。', '[]', 1, 0, 97, 1, '2026-10-26 20:05:00', '2026-10-26 20:05:00'),
  (8008, 4002, 6030, 24, 4, '资料包结构清晰，面试真题更新到今年，就是部分 PDF 有点大。', '[]', 0, 0, 61, 1, '2026-10-27 09:50:00', '2026-10-27 09:50:00'),
  (8009, 2006, 6033, 15, 5, '作为同好，能看到完整世界观附录非常满足，期待下一部。', '[]', 0, 1, 24, 1, '2026-10-28 23:10:00', '2026-10-28 23:10:00'),
  (8010, 3001, 6035, 29, 5, '加印版没有色差，随书书签也在，晒一张书脊排排站。', '[]', 1, 0, 178, 1, '2026-10-29 20:00:00', '2026-10-29 20:00:00'),
  (8011, 5002, 6052, 28, 4, '直播画质不错，权益核销后还能回看，体验比想象中完整。', '[]', 0, 0, 33, 1, '2026-10-30 21:30:00', '2026-10-30 21:30:00'),
  (8012, 1003, 6054, 12, 3, '内容很好，但实体周边比承诺晚了两周，希望下次进度同步更及时。', '[]', 0, 0, 19, 1, '2026-10-31 11:00:00', '2026-10-31 11:00:00'),
  (8013, 2002, 6057, 3, 5, '结尾那一封信看完沉默了很久，电子档还附了作者手记。', '[]', 0, 0, 73, 1, '2026-11-01 22:40:00', '2026-11-01 22:40:00'),
  (8014, 3004, 6058, 10, 5, '第二批补款也发了，包装泡沫很厚，摆柜子里正合适。', '[]', 1, 0, 96, 1, '2026-11-02 19:20:00', '2026-11-02 19:20:00'),
  (8015, 3008, 6059, 17, 4, '卡牌手感不错，收纳盒略紧，整体对得起这个档位。', '[]', 0, 0, 41, 1, '2026-11-03 20:45:00', '2026-11-03 20:45:00'),
  (8016, 4002, 6062, 8, 5, '按模块整理的面经很省时间，附的答题框架直接能用。', '[]', 0, 0, 52, 1, '2026-11-04 10:30:00', '2026-11-04 10:30:00'),
  (8017, 2006, 6065, 29, 5, '更新日志里提到的隐藏章节真的做了，算是意外惊喜。', '[]', 0, 0, 35, 1, '2026-11-05 21:15:00', '2026-11-05 21:15:00'),
  (8018, 3001, 6067, 13, 4, '整体满意，唯一小遗憾是特典明信片少了随机款。', '[]', 1, 0, 64, 1, '2026-11-06 20:30:00', '2026-11-06 20:30:00');
INSERT INTO `project_report` (`report_id`, `target_type`, `target_id`, `project_id`, `user_id`, `reason_code`, `description`, `evidence`, `status`, `handle_note`, `handle_time`, `gmt_create`, `gmt_modified`) VALUES
  (9001, 'project', 1004, 1004, 6, 'fraud', '怀疑众筹页面演示素材与他人作品高度相似，请核实原创性。', '[]', 'accepted', '已要求创作者补充素材授权说明，页面暂标注「审核中」。', '2026-11-03 15:00:00', '2026-11-02 09:12:00', '2026-11-03 15:00:00'),
  (9002, 'project', 3004, 3004, 12, 'infringe', '手办造型可能侵犯某动漫角色形象权。', '[]', 'accepted', '已下架相关档位，创作者提交授权文件后恢复。', '2026-11-04 11:20:00', '2026-11-03 18:40:00', '2026-11-04 11:20:00'),
  (9003, 'review', 8003, 5002, 20, 'other', '评价内容与企划无关，疑似广告。', '[]', 'rejected', '复核为正常观演反馈，保留评价。', '2026-11-05 10:05:00', '2026-11-04 21:30:00', '2026-11-05 10:05:00'),
  (9004, 'feed', 22, NULL, 18, 'false_claim', '动态中「包过」承诺涉嫌虚假宣传。', '[]', 'accepted', '已删除违规表述并提示创作者修改。', '2026-11-05 16:30:00', '2026-11-05 09:00:00', '2026-11-05 16:30:00'),
  (9005, 'project', 2003, 2003, 24, 'other', '更新频率过低，担心无法按期交付。', '[]', 'pending', NULL, NULL, '2026-11-06 08:20:00', '2026-11-06 08:20:00'),
  (9006, 'review', 8012, 1003, 21, 'other', '对该评价的真实性有疑问。', '[]', 'pending', NULL, NULL, '2026-11-06 19:00:00', '2026-11-06 19:00:00'),
  (9007, 'feed', 8, NULL, 30, 'porn', '配图疑似违规内容。', '[]', 'rejected', '人工复核为正常插画，不构成违规。', '2026-11-06 20:10:00', '2026-11-06 18:30:00', '2026-11-06 20:10:00'),
  (9008, 'project', 4006, 4006, 9, 'false_claim', '宣传「内推必过」与实际服务不符。', '[]', 'accepted', '已要求删除绝对化承诺并补充服务说明。', '2026-11-07 09:40:00', '2026-11-07 08:00:00', '2026-11-07 09:40:00');
