  (1, 1, 4, '{"userId":4,"userName":"白昼"}', '《山海食堂》把经营和志怪故事揉在一起，试玩版手感很惊喜。', '发现一个把山海经做成食堂的独立游戏', '白昼', NULL, 0.00, 0, 0, 27, 4, 1, 340, 11, 99, 0, 1, 0, 0, '[]', '[]', '["企划推荐","独立游戏"]', '[{"topicId":1,"name":"新企划发现"}]', NULL, '2026-10-02 12:00:00', '2026-11-02 12:00:00'),
